      Lesson(
        id: 'linux-operations-paquetes',
        title: 'Paquetes, repositorios y mantenimiento',
        minutes: 15,
        intro: 'El puesto ficticio conserva una aplicación instalada y metadatos antiguos del gestor; el taller debe distinguir inventario local, actualizaciones disponibles y cambios autorizados.',
        steps: [
